<?php if ( ! defined( 'ABSPATH' ) ) exit; $offers = $args['offers']; ?>
<dialog id="nsp-special-offers" data-visitor-key="<?php echo esc_attr( 'nsp_offers_seen_' . md5( home_url( '/' ) ) ); ?>" aria-labelledby="nsp-offers-title" aria-describedby="nsp-offers-intro" dir="<?php echo nsp_is_arabic() ? 'rtl' : 'ltr'; ?>">
    <header class="nsp-offers-heading"><div><span class="nsp-offers-eyebrow"><?php nsp_te( 'NEW SUPER PRIME', 'نيو سوبر برايم' ); ?></span><h2 id="nsp-offers-title" tabindex="-1"><?php nsp_te( 'Special Offers', 'عروض خاصة' ); ?></h2><p id="nsp-offers-intro"><?php nsp_te( 'Great service. Clear prices. Book any day.', 'خدمة مميزة. أسعار واضحة. احجز في أي يوم.' ); ?></p></div><button type="button" data-offers-close aria-label="<?php nsp_ta( 'Close special offers', 'إغلاق العروض الخاصة' ); ?>">×</button></header>
    <div class="nsp-offers-body" aria-roledescription="carousel" aria-label="<?php nsp_ta( 'Service offers', 'عروض الخدمات' ); ?>">
        <?php foreach ( $offers as $index=>$offer ) : ?>
        <article class="nsp-offer-slide" data-offer-slide <?php if ( $index ) echo 'hidden'; ?>>
            <div class="nsp-offer-photo"><img src="<?php echo esc_url( $offer['image_url'] ); ?>" alt=""><?php if ( $offer['warranty'] ) : ?><span><?php nsp_te( 'BEST VALUE', 'أفضل قيمة' ); ?></span><?php endif; ?></div>
            <div class="nsp-offer-details"><p class="nsp-offer-service"><?php echo esc_html( nsp_service_ar( $offer['service'], 'title' ) ?: $offer['service'] ); ?></p><h3><?php echo esc_html( nsp_t( $offer['name'], $offer['name_ar'] ) ); ?></h3><strong class="nsp-offer-price"><?php echo esc_html( nsp_catalog_price( $offer['package']['package_price'] ) ); ?></strong><p class="nsp-offer-gift"><i class="fas fa-gift" aria-hidden="true"></i> <?php echo esc_html( nsp_t( $offer['package']['package_perk'], $offer['perk_ar'] ) ); ?></p><p class="nsp-offer-terms"><?php if ( $offer['warranty'] ) : ?><i class="fas fa-shield-alt" aria-hidden="true"></i> <?php nsp_te( '30-Day Warranty (1 Revisit)', 'ضمان ٣٠ يوماً (زيارة متابعة واحدة)' ); ?><?php else : nsp_te( 'No advance payment · Pay after work', 'بدون دفعة مقدمة · الدفع بعد العمل' ); endif; ?></p><?php nsp_booking_button( $offer['id'], nsp_t( 'Book this offer →', 'احجز هذا العرض ←' ), $offer['image_url'], $offer['index'] ); ?></div>
        </article>
        <?php endforeach; ?>
    </div>
    <footer class="nsp-offers-navigation"><button type="button" data-offers-prev aria-label="<?php nsp_ta( 'Previous offer', 'العرض السابق' ); ?>">←</button><div class="nsp-offers-dots" role="group" aria-label="<?php nsp_ta( 'Choose an offer', 'اختر عرضاً' ); ?>"><?php foreach ( $offers as $index=>$offer ) : ?><button type="button" data-offer-dot="<?php echo (int) $index; ?>" aria-pressed="<?php echo $index ? 'false' : 'true'; ?>" aria-label="<?php echo esc_attr( nsp_t( $offer['service'] . ': ' . $offer['name'], $offer['name_ar'] ) ); ?>"></button><?php endforeach; ?></div><span data-offers-counter dir="ltr" role="status" aria-live="polite">1 / <?php echo count( $offers ); ?></span><button type="button" data-offers-next aria-label="<?php nsp_ta( 'Next offer', 'العرض التالي' ); ?>">→</button></footer>
</dialog>
